def query(n,text,count,note):
 m=read(n+'.json');return dict(text=text,method=m['method'],url=m['url'],payload=m['payload'],checked_at_utc=m['checked_at_utc'],http_status=m['status'],effective_url=m['effective_url'],result_count=count,count_note=note,match_type='exact_title',evidence_path=m['evidence_path'],metadata_path=m['metadata_path'])
def robot(p,u):
 m=read(p);d=robots_decision(E/p,u);return dict(url=m['url'],status=m['status'],checked_at_utc=m['checked_at_utc'],evidence_path='evidence/'+p,decision=d['decision'],note=d['note'])
def size(value,unit,date,url,quality,note,evidence):return dict(value=value,unit=unit,date=date,source_url=url,quality=quality,note=note,evidence_path=evidence)
